def prose(s):
 s=re.sub(r'(?<![0-9])([A-Za-z]{2,})(?=\d)',r'\1 ',s)
 s=re.sub(r'(?<!\d)([.;:])(?=[A-Za-z0-9])',r'\1 ',s)
 return re.sub(r',(?=\S)',', ',s)
def frame(kind,formula,caption,**v):
 caption=prose(caption)
 return dict(nodes=[],edges=[],snapshot=dict(kind=kind,**v),caption=caption,captionHtml='<p>'+caption+'</p>',formula=formula,formulaHtml='<div class="formula-block">'+mathml.render(formula,True).replace('<mo>-</mo>','<mo>−</mo>')+'</div>',line=0,metrics={},teaching=dict(operation=caption,why=caption,currentState=v,initial=False,activeLine=0,changes=[],checks=[],reading='Read the actual input, its declared width or scale, and the named calculation checkpoint. Pending entries are not established numeric results.'))
def scene(name,title,description,frames):
 title=prose(title);description=prose(description)
 if frames[0]['snapshot']['kind']=='adder':description+=r' Each FA block is a one-bit full adder: $a+b+c_{\mathrm{in}}=r+2c_{\mathrm{out}}$. Rows are ordered by increasing bit position, so the least significant bit is at the left.'
 frames[0]['teaching']['initial']=True;S['number-question-'+name]=dict(id='number-question-'+name,title=title,description=description,descriptionHtml=mathml.markdown_math(description,md),invariant=description,visual=dict(type='enumeration',claim=description),code=['Decode the stated input; perform the named exact operation; check range or error assumptions; interpret the result'],frames=frames)
def signed(a,w):return a-(1<<w) if a>=(1<<(w-1)) else a
def adder(w,a,b,label):
 rows=[];c=0
 for i in range(w):
  t=((a>>i)&1)+((b>>i)&1)+c;rows.append([i,(a>>i)&1,(b>>i)&1,c,t%2,t//2]);c=t//2
 exact=signed(a,w)+signed(b,w);u=(a+b)%(1<<w);v=not -(1<<(w-1))<=exact<(1<<(w-1));out=[]
 for k in range(w+1):
  out.append(frame('adder',rf'{signed(a,w)}+({signed(b,w)})={exact}',label+(': operands and initial carry zero; bit results pending.' if not k else f': completed low {k} bit positions; final flags are interpreted only at full width.'),w=w,a=a,b=b,rows=rows,completed=k,stored=u,signedResult=signed(u,w),carry=c,overflow=int(v),exact=exact))
 return out
